      "summary": "首页 > 科研进展 近二十年来，黑洞热力学研究揭示了黑洞与流体系统之间的相似性——带电的Anti-de Sitter（AdS）黑洞存在小黑洞—大黑洞一级相变。然而，一个关键问题始终悬而未决——临界点上的“超临界”区域，黑洞表现出怎样的热力学行为？长期以来，人们对此知之甚少，已有的超临界相转变线也不具有普适性。 近日，中",
